<template><div class="space-y-4"><div class="grid gap-4 md:grid-cols-2"><el-input v-model="header" type="textarea" :rows="5" placeholder="Header JSON"/><el-input v-model="payload" type="textarea" :rows="5" placeholder="Payload JSON"/></div><el-input v-model="secret" placeholder="Secret（HS256）" show-password/><el-button type="primary" size="small" @click="generate">生成 JWT</el-button><el-input v-if="token" v-model="token" type="textarea" :rows="4" readonly/></div></template>
<script setup lang="ts">import { ref } from 'vue'; import { ElMessage } from 'element-plus'; const header=ref('{"alg":"HS256","typ":"JWT"}'); const payload=ref('{"sub":"user","iat":' + Math.floor(Date.now()/1000) + '}'); const secret=ref(''); const token=ref(''); const enc=(bytes:Uint8Array)=>{let binary='';bytes.forEach(byte=>binary+=String.fromCharCode(byte));return btoa(binary).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_')}; const encText=(text:string)=>enc(new TextEncoder().encode(text)); const generate=async()=>{try{const h=encText(JSON.stringify(JSON.parse(header.value)));const p=encText(JSON.stringify(JSON.parse(payload.value)));const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret.value),{name:'HMAC',hash:'SHA-256'},false,['sign']);const sig=await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(`${h}.${p}`));token.value=`${h}.${p}.${enc(new Uint8Array(sig))}`;ElMessage.success('JWT 已生成')}catch{ElMessage.error('Header 或 Payload JSON 格式错误')}};</script>
